class LogTransformer_Scratch:
    """Log1p-Transformation für rechts-schiefe Verteilungen."""

    def fit(self, X):
        # Prüfe ob Daten nicht-negativ sind
        if (X < 0).any():
            raise ValueError("Log-Transformation erfordert X >= 0")
        return self

    def transform(self, X):
        return np.log1p(X)   # log(x + 1) — vermeidet log(0) = -inf

    def inverse_transform(self, X_log):
        return np.expm1(X_log)  # e^x - 1 (Umkehrung von log1p)

    def fit_transform(self, X):
        return self.fit(X).transform(X)

import numpy as np

class VarianceThreshold_Scratch:
    """Entfernt Features mit Varianz unter dem Schwellenwert."""

    def __init__(self, threshold=0.0):
        self.threshold = threshold

    def fit(self, X):
        self.variances_ = X.var(axis=0)          # Varianz jeder Spalte
        self.mask_ = self.variances_ >= self.threshold
        self.support_ = np.where(self.mask_)[0]  # Indizes der behaltenen Features
        return self

    def transform(self, X):
        return X[:, self.mask_]

    def fit_transform(self, X):
        return self.fit(X).transform(X)

import numpy as np

class SimpleKNN:
    """Einfachster ML-Algorithmus: 1-Nearest-Neighbor."""

    def fit(self, X_train, y_train):
        # "Training" = Daten merken (kein echtes Lernen bei KNN!)
        self.X_train = np.array(X_train)
        self.y_train = np.array(y_train)

    def predict(self, X_test):
        X_test = np.array(X_test)
        predictions = []
        for x in X_test:
            # Euklidische Distanz zu allen Trainingspunkten
            distances = np.sqrt(np.sum((self.X_train - x) ** 2, axis=1))
            # Index des nächsten Nachbarn
            nearest_idx = np.argmin(distances)
            # Label des nächsten Nachbarn übernehmen
            predictions.append(self.y_train[nearest_idx])
        return np.array(predictions)

    def score(self, X_test, y_test):
        y_pred = self.predict(X_test)
        return np.mean(y_pred == np.array(y_test))

class SimpleLinearRegression:
    """Lineare Regression: y = w*x + b (eine Feature)."""

    def fit(self, X, y):
        X, y = np.array(X).flatten(), np.array(y)
        n = len(X)
        # Analytische Lösung der kleinsten Quadrate
        self.w = (n * np.sum(X*y) - np.sum(X)*np.sum(y)) / \
                 (n * np.sum(X**2) - np.sum(X)**2)
        self.b = (np.sum(y) - self.w * np.sum(X)) / n

    def predict(self, X):
        return self.w * np.array(X).flatten() + self.b

    def mse(self, X, y):
        y_pred = self.predict(X)
        return np.mean((y_pred - np.array(y))**2)

import numpy as np

class HardMarginSVM:
    """
    Lineare SVM (Hard-Margin) via Subgradient Descent.
    Nur für linear separierbare Daten geeignet.
    """

    def __init__(self, lr=0.01, n_iter=1000):
        self.lr = lr
        self.n_iter = n_iter

    def fit(self, X, y):
        # Labels müssen -1 oder +1 sein
        y_ = np.where(y <= 0, -1, 1)
        n, d = X.shape
        self.w = np.zeros(d)
        self.b = 0.0

        for _ in range(self.n_iter):
            for i, xi in enumerate(X):
                # Wenn Punkt NICHT korrekt im Margin: Gradient-Schritt
                if y_[i] * (np.dot(self.w, xi) + self.b) < 1:
                    self.w += self.lr * (y_[i] * xi - 2 * (1/self.n_iter) * self.w)
                    self.b += self.lr * y_[i]
                else:
                    # Nur Regularisierung
                    self.w -= self.lr * (2 * (1/self.n_iter) * self.w)

    def predict(self, X):
        return np.sign(np.dot(X, self.w) + self.b).astype(int)

    def score(self, X, y):
        y_ = np.where(y <= 0, -1, 1)
        return np.mean(self.predict(X) == y_)

    @property
    def margin(self):
        """Margin-Breite = 2 / ||w||"""
        norm = np.linalg.norm(self.w)
        return 2 / norm if norm > 0 else float('inf')

