class LinearSVM_SGD:
    """
    Lineare SVM via Stochastischem Gradient Descent.
    Skaliert auf große Datensätze (äquivalent zu LinearSVC).
    """

    def __init__(self, C=1.0, lr=0.01, n_epochs=100, random_state=42):
        self.C = C
        self.lr = lr
        self.n_epochs = n_epochs
        self.rng = np.random.default_rng(random_state)

    def fit(self, X, y):
        y_ = np.where(y <= 0, -1, 1)
        n, d = X.shape
        self.w = np.zeros(d)
        self.b = 0.0

        for epoch in range(self.n_epochs):
            # Lernrate abkühlen lassen (Learning Rate Schedule)
            lr_t = self.lr / (1 + epoch * 0.1)

            # Zufällige Reihenfolge
            indices = self.rng.permutation(n)
            for i in indices:
                xi, yi = X[i], y_[i]
                if yi * (np.dot(self.w, xi) + self.b) < 1:
                    # Hinge-Verlust: Update Richtung
                    self.w = (1 - lr_t) * self.w + lr_t * self.C * yi * xi
                    self.b += lr_t * self.C * yi
                else:
                    # Nur Gewichts-Decay
                    self.w = (1 - lr_t) * self.w

    def decision_function(self, X):
        return np.dot(X, self.w) + self.b

    def predict(self, X):
        return np.sign(self.decision_function(X)).astype(int)

    def score(self, X, y):
        y_ = np.where(y <= 0, -1, 1)
        return np.mean(self.predict(X) == y_)

import numpy as np

class KMeans:
    """k-means Clustering (Lloyd's Algorithmus) von Scratch."""

    def __init__(self, k=3, max_iter=300, tol=1e-4, random_state=42):
        self.k = k
        self.max_iter = max_iter
        self.tol = tol
        self.rng = np.random.default_rng(random_state)

    def _init_centroids(self, X):
        """k-means++ Initialisierung."""
        n = len(X)
        # Ersten Centroid zufällig wählen
        centroids = [X[self.rng.integers(n)]]
        for _ in range(self.k - 1):
            # Distanz zum nächsten bestehenden Centroid
            dists = np.array([
                min(np.sum((x - c)**2) for c in centroids)
                for x in X
            ])
            # Proportional zu Distanz² wählen
            probs = dists / dists.sum()
            idx = self.rng.choice(n, p=probs)
            centroids.append(X[idx])
        return np.array(centroids)

    def fit(self, X):
        X = np.array(X)
        self.centroids_ = self._init_centroids(X)
        self.inertia_history_ = []

        for iteration in range(self.max_iter):
            # Assignment-Schritt
            labels = self._assign(X)

            # Update-Schritt: neue Centroids
            new_centroids = np.array([
                X[labels == k].mean(axis=0) if np.sum(labels == k) > 0
                else self.centroids_[k]          # leeren Cluster behalten
                for k in range(self.k)
            ])

            # Inertia berechnen
            inertia = sum(
                np.sum((X[labels == k] - new_centroids[k])**2)
                for k in range(self.k)
            )
            self.inertia_history_.append(inertia)

            # Konvergenz prüfen
            shift = np.max(np.linalg.norm(new_centroids - self.centroids_, axis=1))
            self.centroids_ = new_centroids
            if shift < self.tol:
                break

        self.labels_ = self._assign(X)
        self.inertia_ = self.inertia_history_[-1]
        self.n_iter_ = iteration + 1
        return self

    def _assign(self, X):
        dists = np.array([
            np.sum((X - c)**2, axis=1)
            for c in self.centroids_
        ])  # Shape: (k, n)
        return np.argmin(dists, axis=0)

    def predict(self, X):
        return self._assign(np.array(X))

import numpy as np

def silhouette_score_scratch(X, labels):
    """Silhouette Score von Scratch."""
    n = len(X)
    k_vals = np.unique(labels)
    scores = []

    for i in range(n):
        ci = labels[i]
        # a(i): mittlere Distanz zu gleicher Klasse
        same = X[labels == ci]
        if len(same) > 1:
            a = np.mean(np.sqrt(np.sum((same - X[i])**2, axis=1)))
        else:
            a = 0.0

        # b(i): minimale mittlere Distanz zu anderen Klassen
        b_vals = []
        for cj in k_vals:
            if cj == ci:
                continue
            other = X[labels == cj]
            b_vals.append(np.mean(np.sqrt(np.sum((other - X[i])**2, axis=1))))
        b = min(b_vals) if b_vals else 0.0

        if max(a, b) > 0:
            scores.append((b - a) / max(a, b))
        else:
            scores.append(0.0)

    return np.mean(scores)

