class DecisionNode:
    """Knoten im Entscheidungsbaum."""
    def __init__(self, feature=None, threshold=None, left=None, right=None, value=None):
        self.feature   = feature      # Split-Feature
        self.threshold = threshold    # Split-Schwellenwert
        self.left      = left         # linker Teilbaum
        self.right     = right        # rechter Teilbaum
        self.value     = value        # Blatt-Vorhersage


class DecisionTreeScratch:
    def __init__(self, max_depth=5, min_samples_split=2):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.root = None

    def gini(self, y):
        n = len(y)
        if n == 0: return 0.0
        _, counts = np.unique(y, return_counts=True)
        probs = counts / n
        return 1.0 - np.sum(probs ** 2)

    def best_split(self, X, y):
        n, n_features = X.shape
        best_gain, best_feat, best_thresh = -1, None, None
        parent_gini = self.gini(y)

        for feat in range(n_features):
            thresholds = np.unique(X[:, feat])
            for t in thresholds:
                left_mask  = X[:, feat] <= t
                right_mask = ~left_mask
                if left_mask.sum() < 1 or right_mask.sum() < 1:
                    continue
                n_l, n_r = left_mask.sum(), right_mask.sum()
                gain = parent_gini - (n_l/n * self.gini(y[left_mask])
                                    + n_r/n * self.gini(y[right_mask]))
                if gain > best_gain:
                    best_gain, best_feat, best_thresh = gain, feat, t
        return best_feat, best_thresh

    def build(self, X, y, depth=0):
        # Stopp-Bedingungen
        if depth >= self.max_depth or len(y) < self.min_samples_split or len(np.unique(y)) == 1:
            return DecisionNode(value=np.bincount(y).argmax())

        feat, thresh = self.best_split(X, y)
        if feat is None:
            return DecisionNode(value=np.bincount(y).argmax())

        left_mask = X[:, feat] <= thresh
        left  = self.build(X[left_mask],  y[left_mask],  depth+1)
        right = self.build(X[~left_mask], y[~left_mask], depth+1)
        return DecisionNode(feature=feat, threshold=thresh, left=left, right=right)

    def fit(self, X, y):
        self.root = self.build(np.array(X), np.array(y))

    def _predict_one(self, x, node):
        if node.value is not None:
            return node.value
        if x[node.feature] <= node.threshold:
            return self._predict_one(x, node.left)
        return self._predict_one(x, node.right)

    def predict(self, X):
        return np.array([self._predict_one(x, self.root) for x in X])

    def score(self, X, y):
        return np.mean(self.predict(X) == np.array(y))

