class RandomForestScratch:
    """Random Forest = Bagging + Feature-Subsampling pro Split."""

    def __init__(self, n_estimators=100, max_features='sqrt',
                 max_depth=None, random_state=42):
        self.n_estimators = n_estimators
        self.max_features = max_features
        self.max_depth = max_depth
        self.rng = np.random.default_rng(random_state)
        self.trees = []

    def fit(self, X, y):
        X, y = np.array(X), np.array(y)
        n, p = X.shape

        if self.max_features == 'sqrt':
            m = max(1, int(np.sqrt(p)))
        elif self.max_features == 'log2':
            m = max(1, int(np.log2(p)))
        else:
            m = p

        self.trees = []
        for i in range(self.n_estimators):
            # Bootstrap-Sample
            idx = self.rng.choice(n, n, replace=True)
            X_boot, y_boot = X[idx], y[idx]

            # DecisionTree mit max_features=m nutzt beim Split nur m Features
            tree = DecisionTreeClassifier(
                max_features=m,          # Feature-Subsampling!
                max_depth=self.max_depth,
                random_state=int(self.rng.integers(100000))
            )
            tree.fit(X_boot, y_boot)
            self.trees.append(tree)

    def predict(self, X):
        preds = np.array([t.predict(X) for t in self.trees])
        return np.array([np.bincount(col.astype(int)).argmax() for col in preds.T])

    def score(self, X, y):
        return np.mean(self.predict(X) == np.array(y))

