def compute_bic_scratch(log_likelihood, n_params, n_samples):
    """BIC = -2*logL + p*log(n)"""
    return -2 * log_likelihood + n_params * np.log(n_samples)

def gmm_n_params(K, d, covariance_type):
    """Anzahl freier Parameter eines GMM."""
    # Mischungsgewichte: K-1
    # Mittelwerte: K*d
    # Kovarianzen: je nach Typ
    pi_params = K - 1
    mu_params = K * d
    if covariance_type == 'full':
        cov_params = K * d * (d + 1) // 2
    elif covariance_type == 'tied':
        cov_params = d * (d + 1) // 2
    elif covariance_type == 'diag':
        cov_params = K * d
    else:  # spherical
        cov_params = K
    return pi_params + mu_params + cov_params

def fbeta_score_scratch(y_true, y_pred, beta):
    """Fβ-Score."""
    tp = ((y_pred==1) & (y_true==1)).sum()
    fp = ((y_pred==1) & (y_true==0)).sum()
    fn = ((y_pred==0) & (y_true==1)).sum()
    prec = tp/(tp+fp) if (tp+fp) > 0 else 0.0
    rec  = tp/(tp+fn) if (tp+fn) > 0 else 0.0
    if prec + rec == 0: return 0.0
    return (1 + beta**2) * prec * rec / (beta**2 * prec + rec)

